// Pixel Dodger – simple canvas game
// Canvas with id="game"
(() => {
  const canvas = document.getElementById('game');
  if (!canvas) return;
  const ctx = canvas.getContext('2d');
  const width = canvas.width = canvas.clientWidth || 400;
  const height = canvas.height = canvas.clientHeight || 600;

  // Player
  const player = { w: 40, h: 20, x: width / 2 - 20, y: height - 30, speed: 5 };

  // Blocks
  const blocks = [];
  let blockSpawnTimer = 0;
  let blockSpawnInterval = 1500; // ms
  let blockSpeed = 2;
  let lastTime = 0;
  let score = 0;
  let gameOver = false;

  // Input
  const keys = {};
  window.addEventListener('keydown', e => (keys[e.key] = true));
  window.addEventListener('keyup', e => (keys[e.key] = false));

  function spawnBlock() {
    const size = Math.random() * 30 + 20;
    const x = Math.random() * (width - size);
    blocks.push({ x, y: -size, w: size, h: size });
  }

  function update(dt) {
    // player movement
    if (keys['ArrowLeft'] || keys['a']) player.x -= player.speed;
    if (keys['ArrowRight'] || keys['d']) player.x += player.speed;
    player.x = Math.max(0, Math.min(width - player.w, player.x));

    // spawn blocks
    blockSpawnTimer += dt;
    if (blockSpawnTimer > blockSpawnInterval) {
      spawnBlock();
      blockSpawnTimer = 0;
    }

    // update blocks
    for (let i = blocks.length - 1; i >= 0; i--) {
      const b = blocks[i];
      b.y += blockSpeed * (dt / 16.67);
      // collision
      if (
        b.x < player.x + player.w &&
        b.x + b.w > player.x &&
        b.y < player.y + player.h &&
        b.y + b.h > player.y
      ) {
        gameOver = true;
      }
      // remove off‑screen
      if (b.y > height) blocks.splice(i, 1);
    }

    // increase difficulty over time
    blockSpeed += dt * 0.00001; // gradual acceleration
    blockSpawnInterval = Math.max(300, blockSpawnInterval - dt * 0.01);
    score = Math.floor((performance.now() - startTime) / 1000);
  }

  function draw() {
    ctx.clearRect(0, 0, width, height);
    // player
    ctx.fillStyle = '#0f0';
    ctx.fillRect(player.x, player.y, player.w, player.h);
    // blocks
    ctx.fillStyle = '#f00';
    blocks.forEach(b => ctx.fillRect(b.x, b.y, b.w, b.h));
    // score
    ctx.fillStyle = '#000';
    ctx.font = '16px sans-serif';
    ctx.fillText('Score: ' + score, 10, 20);
    if (gameOver) {
      ctx.fillStyle = 'rgba(0,0,0,0.5)';
      ctx.fillRect(0, 0, width, height);
      ctx.fillStyle = '#fff';
      ctx.font = '30px sans-serif';
      ctx.fillText('Game Over', width / 2 - 80, height / 2);
    }
  }

  function loop(timestamp) {
    if (!lastTime) lastTime = timestamp;
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    if (!gameOver) requestAnimationFrame(loop);
  }

  const startTime = performance.now();
  requestAnimationFrame(loop);
})();
